#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum OwnerVerdict {
    Missing,
    Ambiguous,
}

impl OwnerVerdict {
    pub(crate) fn diagnostic(self) -> Diagnostic {
        match self {
            Self::Ambiguous => Diagnostic::io(
                "SPX-H006",
